-- Generated by drizzle-kit (the table) plus hand-written SQL (M3a, D-110 addendum): the ground
-- truth of a frozen dataset version. `eval.ratings` and `eval.assignments` hold one current row per
-- (rater, article), so a post-freeze correction (which branches a child version) or an assignment
-- appended after branching would otherwise reach a new run on the frozen parent; the raters (their
-- participant, context name and languages) are captured too, so a rater added later never joins it.
-- The row is written once, in the transaction that freezes the version, and never changes.
CREATE TABLE "eval"."dataset_truth" (
	"dataset_version" text PRIMARY KEY NOT NULL,
	"raters" jsonb NOT NULL,
	"ratings" jsonb NOT NULL,
	"assignments" jsonb NOT NULL,
	"cards" jsonb NOT NULL,
	"facet_labels" jsonb NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL
);
--> statement-breakpoint
ALTER TABLE "eval"."dataset_truth" ADD CONSTRAINT "dataset_truth_dataset_version_datasets_version_fk" FOREIGN KEY ("dataset_version") REFERENCES "eval"."datasets"("version") ON DELETE restrict ON UPDATE no action;
--> statement-breakpoint
-- Grants (spec 02 §7): the eval CLI's worker role, like every other eval table.
GRANT SELECT, INSERT, UPDATE, DELETE ON eval.dataset_truth TO bantoozi_worker;--> statement-breakpoint
-- Append-only: written once for a frozen version, never updated or deleted.
CREATE FUNCTION eval.dataset_truth_append_only() RETURNS trigger
LANGUAGE plpgsql SET search_path = pg_catalog, public, pg_temp AS $$
BEGIN
  IF TG_OP <> 'INSERT' THEN
    RAISE EXCEPTION 'eval.dataset_truth rows are immutable; a correction creates a new dataset version'
      USING ERRCODE = 'check_violation', CONSTRAINT = TG_NAME;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM eval.datasets d
                  WHERE d.version = NEW.dataset_version AND d.frozen_at IS NOT NULL) THEN
    RAISE EXCEPTION 'dataset version % is not frozen; its ground truth is captured when it freezes', NEW.dataset_version
      USING ERRCODE = 'check_violation', CONSTRAINT = TG_NAME;
  END IF;
  RETURN NEW;
END $$;--> statement-breakpoint
CREATE TRIGGER dataset_truth_append_only BEFORE INSERT OR UPDATE OR DELETE ON eval.dataset_truth
  FOR EACH ROW EXECUTE FUNCTION eval.dataset_truth_append_only();
